using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Mmorpg.Runtime;
using Object=UnityEngine.Object;
[InitializeOnLoad]
public static class Ground13RImporter
{
 public const string Source="ArtSource/Labs/World2026/Ground13R/",Art="Assets/Mmorpg/Art/Experimental/ValdoriaGround13R/",Scene="Assets/Mmorpg/Scenes/ValdoriaGround13RLab.unity";
 static Ground13RImporter(){EditorApplication.update+=Tick;}
 static Material Neutral(Material source){string path=Art+"NeutralStudy.mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing)return existing;var m=new Material(source){name="Ground13R neutral volume study"};m.SetColor("_Color",new Color(.58f,.59f,.57f,1));AssetDatabase.CreateAsset(m,path);return m;}
 public static object TuneNeutral(){if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().path!=Scene)throw new IOException("Stopped Ground13R lab required");var lab=Object.FindAnyObjectByType<Ground13RLab>();var so=new SerializedObject(lab);so.FindProperty("clay").objectReferenceValue=Neutral((Material)so.FindProperty("clay").objectReferenceValue);so.ApplyModifiedPropertiesWithoutUndo();EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return "Shared neutral study material assigned to both blockouts";}
 public static object Queue(){if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().isDirty||Directory.Exists(Art)||File.Exists(Scene))throw new IOException("Refuse playing, dirty scene or existing destination");SessionState.SetBool("Ground13R.Build",true);return "Queued new visual-only lab";}
 static void Tick(){if(!SessionState.GetBool("Ground13R.Build",false)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;SessionState.SetBool("Ground13R.Build",false);try{File.WriteAllText("Temp/Ground13R-build.json",JsonConvert.SerializeObject(Build(),Formatting.Indented));}catch(Exception e){File.WriteAllText("Temp/Ground13R-build.json",e.ToString());}}
 static Mesh Mesh(JToken g,Mesh target=null){var m=target?target:new Mesh{indexFormat=IndexFormat.UInt32};m.Clear();m.SetVertices(g["vertices"].Select(v=>new Vector3((float)v[0],(float)v[1],(float)v[2])).ToList());m.SetUVs(0,g["uv"].Select(v=>new Vector2((float)v[0],(float)v[1])).ToList());if(g["selector"]!=null)m.SetUVs(1,g["selector"].Select(v=>new Vector2((float)v[0],(float)v[1])).ToList());m.SetColors(g["colors"].Select(v=>new Color((float)v[0],(float)v[1],(float)v[2],(float)v[3])).ToList());m.SetTriangles(g["triangles"].Select(v=>(int)v).ToArray(),0);m.RecalculateBounds();return m;}
 static object Build(){if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().isDirty||Directory.Exists(Art)||File.Exists(Scene))throw new IOException("Refuse overwrite");NatureReference10Importer.Verify(Source+"ShapeV6/");Directory.CreateDirectory(Art);AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(Ground13Importer.Scene);EditorSceneManager.SaveScene(scene,Scene,true);scene=EditorSceneManager.OpenScene(Scene);var old=Object.FindAnyObjectByType<Ground13Lab>();old.Select(3);var so=new SerializedObject(old);var hist=so.FindProperty("originalRelief");var ground12=Enumerable.Range(0,hist.arraySize).Select(i=>(Renderer)hist.GetArrayElementAtIndex(i).objectReferenceValue).ToArray();var oldRoot=(GameObject)so.FindProperty("terraces").objectReferenceValue;var clay=Neutral((Material)so.FindProperty("clay").objectReferenceValue);var root=new GameObject("Ground13R geology - same physical foot");var geometry=JObject.Parse(File.ReadAllText(Source+"ShapeV6/visual-relief.json"));var top=new Material(Shader.Find("Valdoria/Ground13RGeology")){name="Ground13R top contacts"};top.SetTexture("_MineralTex",AssetDatabase.LoadAssetAtPath<Texture2D>(Ground13Importer.Art+"StratifiedFace.png"));AssetDatabase.CreateAsset(top,Art+"TopContacts.mat");var stone=AssetDatabase.LoadAssetAtPath<Material>(Ground13Importer.Art+"StratifiedFace.mat");
  foreach(var g in geometry["groups"]){int row=(int)g["row"];string kind=(string)g["kind"];string name="Geology_"+row+"_"+kind;var mesh=Mesh(g);mesh.name=name;AssetDatabase.CreateAsset(mesh,Art+name+".asset");var go=new GameObject(name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=kind=="stone"?stone:top;rr.sortingOrder=100-Mathf.RoundToInt((48-(row+1))*16)+(kind=="top"?0:1);}
  new GameObject("Ground13R - A12 B13 C13R Dclay Eoldclay").AddComponent<Ground13RLab>().Configure(old,ground12,oldRoot,root,clay);Object.FindAnyObjectByType<ValdoriaR9ProfileIsolation>().ConfigureTemporaryProfile("ValdoriaGround13R/IsolatedProfile");EditorSceneManager.SaveScene(scene);if(File.Exists(Source+"ExportV4/top-atlas.png"))ImportPainting();AssetDatabase.SaveAssets();return new{scene=Scene,renderers=root.GetComponentsInChildren<Renderer>().Length,sharedWaterAndPacking=true,physicalChange=false};}
 public static object ImportPainting(){if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().path!=Scene)throw new IOException("Stopped Ground13R scene required");NatureReference10Importer.Verify(Source+"ExportV4/");string path=Art+"TopContactsV4.png";if(File.Exists(path))throw new IOException("Refuse texture overwrite");File.Copy(Source+"ExportV4/top-atlas.png",path);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Default;i.npotScale=TextureImporterNPOTScale.None;i.filterMode=FilterMode.Point;i.mipmapEnabled=false;i.textureCompression=TextureImporterCompression.Uncompressed;i.wrapMode=TextureWrapMode.Clamp;i.maxTextureSize=2048;var p=i.GetDefaultPlatformTextureSettings();p.format=TextureImporterFormat.RGB24;i.SetPlatformTextureSettings(p);i.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>(Art+"TopContacts.mat");mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();return new{texture=path,physicsChange=false};}
 public static object RefreshGeometry()
 {
  if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().path!=Scene||EditorSceneManager.GetActiveScene().isDirty)throw new IOException("Clean stopped Ground13R scene required");
  NatureReference10Importer.Verify(Source+"ShapeV6/");var groups=JObject.Parse(File.ReadAllText(Source+"ShapeV6/visual-relief.json"))["groups"].ToDictionary(g=>"Geology_"+(int)g["row"]+"_"+(string)g["kind"]);
  var lab=Object.FindAnyObjectByType<Ground13RLab>();var so=new SerializedObject(lab);var root=(GameObject)so.FindProperty("newRoot").objectReferenceValue;var filters=root.GetComponentsInChildren<MeshFilter>(true).ToDictionary(f=>f.name);var top=AssetDatabase.LoadAssetAtPath<Material>(Art+"TopContacts.mat");var stone=AssetDatabase.LoadAssetAtPath<Material>(Ground13Importer.Art+"StratifiedFace.mat");top.shader=Shader.Find("Valdoria/Ground13RGeology");top.SetTexture("_MineralTex",stone.mainTexture);EditorUtility.SetDirty(top);
  foreach(var pair in groups){MeshFilter f;if(!filters.TryGetValue(pair.Key,out f)){string path=Art+pair.Key+".asset";if(File.Exists(path))throw new IOException("Unexpected existing mesh "+path);var go=new GameObject(pair.Key);go.transform.SetParent(root.transform,false);f=go.AddComponent<MeshFilter>();f.sharedMesh=new Mesh{indexFormat=IndexFormat.UInt32,name=pair.Key};AssetDatabase.CreateAsset(f.sharedMesh,path);go.AddComponent<MeshRenderer>();}
   if(!AssetDatabase.GetAssetPath(f.sharedMesh).StartsWith(Art))throw new IOException("Refuse foreign mesh");Mesh(pair.Value,f.sharedMesh);EditorUtility.SetDirty(f.sharedMesh);var rr=f.GetComponent<MeshRenderer>();string kind=(string)pair.Value["kind"];int row=(int)pair.Value["row"];rr.sharedMaterial=kind=="stone"?stone:top;rr.sortingOrder=100-Mathf.RoundToInt((48-(row+1))*16)+(kind=="top"?0:1);
  }
  foreach(var f in filters.Values.Where(f=>!groups.ContainsKey(f.name)))Object.DestroyImmediate(f.gameObject);
  lab.RefreshPresentation();EditorUtility.SetDirty(lab);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return new{updated=groups.Count,physicalChange=false};
 }
}
